/* HEXA BATTLEGROUNDS setup — PART 59 OF 80. Run parts in order. Safe to re-run. */ create or replace function _br_step(p_arena uuid) returns boolean language plpgsql as $$ declare a arenas; r record; pl float8[]; v_loc text; c float8[]; v_changed boolean := false; xy float8[]; begin select * into a from arenas where id = p_arena; if a.id is null then return false; end if; if a.phase = 'shuttle' and (a.overlay -> 'flight' ->> 't1') is distinct from to_jsonb(a.shuttle_arrive_at) #>> '{}' then update arenas set overlay = overlay || jsonb_build_object('flight', jsonb_build_object( 't0', a.shuttle_arrive_at - _secs(_cfg(a.event_id, 'shuttle_seconds')), 't1', a.shuttle_arrive_at)) where id = p_arena; v_changed := true; end if; if a.phase in ('shuttle', 'roles') then if _auto_roles(p_arena) then v_changed := true; end if; end if; if a.phase in ('lobby', 'boarding') and (a.plane_t0 is not null or a.zone_shrink_until is not null or a.overlay ? 'plane') then update arenas set plane_t0 = null, plane_t1 = null, zone_shrink_from = null, zone_shrink_until = null, overlay = overlay - 'plane' - 'flight' where id = p_arena; update teams set vehicle = 'none', buggy_x = null, buggy_y = null, kills = 0, fight_at = null where arena_id = p_arena; v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'br_mode') = 1 and (a.plane_t0 is null or a.plane_t1 < a.play_started_at) then perform _plane_launch(p_arena); v_changed := true; select * into a from arenas where id = p_arena; end if; if a.phase = 'play' then for r in select t.id, t.number, l.x, l.y from teams t join locations l on l.id = t.travel_to where t.arena_id = p_arena and not t.dropped and t.state = 'traveling' and t.travel_arrive_at <= now() loop xy := _buggy_bay(r.number, r.x, r.y); update teams set pos_x = r.x + ((r.number * 37) % 9 - 4) * 0.0012, pos_y = r.y + ((r.number * 53) % 9 - 4) * 0.0012, pos_at = now(), vel_x = 0, vel_y = 0, vehicle = case when _cfg(a.event_id, 'br_mode') = 1 then 'none' else 'in' end, buggy_x = xy[1], buggy_y = xy[2] where id = r.id; end loop; update teams t set pos_x = l.x, pos_y = l.y, pos_at = now() from locations l where l.id = t.travel_to and t.arena_id = p_arena and t.dropped and t.state = 'traveling' and t.travel_arrive_at <= now(); pl := _plane_xy(a); if pl is not null and pl[3] >= 0.8 then c := _zone_circle(a.event_id, a.zone_stage); for r in select id from teams where arena_id = p_arena and ready and not dropped and state = 'idle' loop select l.id into v_loc from locations l where l.enabled and l.kind not in ('start', 'stairs') and l.level = 0 and _in_circle(c, l.x, l.y) order by (l.x - least(0.95, greatest(0.05, pl[1]))) ^ 2 + (l.y - least(0.95, greatest(0.05, pl[2]))) ^ 2 + random() * 0.004 limit 1; if v_loc is not null then perform _do_jump(r.id, v_loc, array[least(0.98, greatest(0.02, pl[1])), least(0.98, greatest(0.02, pl[2]))]); v_changed := true; end if; end loop; end if; end if; if a.zone_shrink_until is not null and a.zone_shrink_until > now() - interval '3 seconds' and (a.overlay -> 'zone' ->> 'shrink_until') is null and a.zone_shrink_until > now() then perform _zone_publish(p_arena); v_changed := true; end if; if a.zone_shrink_until is not null and a.zone_shrink_until <= now() and (a.overlay -> 'zone' ->> 'shrink_until') is not null then perform _zone_publish(p_arena); v_changed := true; end if; return v_changed; end $$; create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; w boolean; begin w := _br_step(p_arena); v := _tick_core(p_arena, p_force); if _br_step(p_arena) or w then v := true; perform _ping_arena(p_arena, 'tick'); end if; if exists (select 1 from bots where arena_id = p_arena) then if _bots_step(p_arena) then v := true; end if; end if; return v; end $$; create or replace function _bot_act(p_team uuid) returns void language plpgsql as $$ declare t teams; b bots; a arenas; mi mission_instances; g locations; bd buildings; lk record; tok text; cur float8[]; c float8[]; spd float8; dt float8; stepd float8; tx float8; ty float8; d float8; nx float8; ny float8; v_dir int := 0; v_goal text; v_res jsonb; v_target uuid; v_weapon text; v_air uuid; v_danger boolean := false; v_brave boolean; v_final boolean := false; v_px float8; v_py float8; v_side int; pl float8[]; w jsonb; v_tok2 text; begin select * into t from teams where id = p_team; select * into b from bots where team_id = p_team; select * into a from arenas where id = t.arena_id; select bp.token into tok from bot_players bp join players p on p.id = bp.player_id where bp.team_id = t.id and p.active and p.role = 'captain' limit 1; if tok is null then return; end if; v_brave := t.number % 3 = 0; cur := _team_xy(t); select k.* into lk from lockdowns k where k.arena_id = a.id and not k.sealed and k.seal_at < now() + interval '14 seconds' and (k.level is null or k.level = t.level) and (k.building = t.bldg or (t.level = 0 and exists (select 1 from buildings bb where bb.id = k.building and cur[1] between bb.x0 and bb.x1 and cur[2] between bb.y0 and bb.y1))) limit 1; v_danger := lk.building is not null and not v_brave; select * into mi from mission_instances where team_id = t.id and status = 'active' order by (kind = 'battle') desc, started_at desc limit 1; if mi.id is not null and not (v_danger and mi.kind in ('mission', 'relay', 'airdrop') and mi.sync_round_id is null) then if b.think_for is distinct from mi.id then update bots set think_for = mi.id, think_ok = random() < b.skill, think_until = now() + _secs((case when mi.kind = 'battle' then 9 + random() * 16 when mi.sync_round_id is not null then 12 + random() * 26 when mi.kind = 'recovery' then 8 + random() * 10 else 14 + random() * 24 end)::numeric) where team_id = t.id; return; end if; if now() < b.think_until or mi.deadline <= now() then return; end if; perform captain_submit(tok, mi.id, _bot_answers(mi, coalesce(b.think_ok, true)), 'bot-' || gen_random_uuid()::text); if not coalesce(b.think_ok, true) then update bots set think_until = now() + _secs((5 + random() * 9)::numeric), think_ok = random() < 0.6 where team_id = t.id; end if; return; end if; if a.phase <> 'play' or t.state in ('recovery', 'traveling') then return; end if; if not t.dropped then if t.state = 'traveling' then return; end if; pl := _plane_xy(a); if pl is null or pl[1] not between 0.04 and 0.96 or pl[2] not between 0.04 and 0.96 or random() > 0.14 then return; end if; c := _zone_circle(a.event_id, a.zone_stage); select l.id into v_goal from locations l where l.enabled and l.kind not in ('start', 'stairs') and l.level = 0 and _in_circle(c, l.x, l.y) and sqrt((l.x - pl[1]) ^ 2 + (l.y - pl[2]) ^ 2) < _cfg(t.event_id, 'glide_range') / 1000.0 * 0.9 order by random() limit 1; if v_goal is not null then perform captain_move(tok, v_goal); end if; update bots set goal = null, done_loc = null, wait_until = null where team_id = t.id; return; end if; if t.hp <= 55 and exists (select 1 from inventory where team_id = t.id and item_id = 'medkit' and qty > 0) then begin perform captain_use_item(tok, 'medkit'); exception when others then null; end; end if; if b.wait_until is not null and now() < b.wait_until and not v_danger then return; end if; if coalesce(a.match_phase, 0) >= _cfg(t.event_id, 'fire_from_phase') then w := _weapon(t.id); select x.id into v_target from teams x where x.arena_id = a.id and x.ready and x.id <> t.id and x.dropped and x.state not in ('recovery', 'traveling') and x.level = t.level and (t.level = 0 or x.bldg is not distinct from t.bldg) and (x.protected_until is null or x.protected_until < now()) and sqrt(((_team_xy(x))[1] - cur[1]) ^ 2 + ((_team_xy(x))[2] - cur[2]) ^ 2) <= (w ->> 'range')::float8 and (t.level > 0 or not _blocked(cur[1], cur[2], (_team_xy(x))[1], (_team_xy(x))[2])) order by ((_team_xy(x))[1] - cur[1]) ^ 2 + ((_team_xy(x))[2] - cur[2]) ^ 2 limit 1; if v_target is not null then for v_tok2 in select bp.token from bot_players bp join players q on q.id = bp.player_id where bp.team_id = t.id and q.active and q.role is not null loop if random() < 0.45 then begin perform squad_fire(v_tok2, v_target); exception when others then null; end; end if; end loop; if t.hp > 35 and not v_danger then return; end if; end if; end if; if not v_danger and t.location_id is not null and b.goal is null then select ad.id into v_air from airdrops ad where ad.arena_id = a.id and ad.status = 'open' and ad.location_id = t.location_id and not exists (select 1 from mission_instances m where m.team_id = t.id and m.airdrop_id = ad.id) limit 1; if v_air is not null then begin perform captain_claim_airdrop(tok, v_air); return; exception when others then null; end; end if; end if; if not v_danger and b.goal is null and t.location_id is not null and t.location_id is distinct from b.done_loc and (select kind from locations where id = t.location_id) not in ('start', 'stairs') and t.visit_missions < _cfg(t.event_id, 'visit_missions') then update bots set done_loc = t.location_id where team_id = t.id; begin perform captain_explore(tok); return; exception when others then null; end; end if; c := _zone_circle(a.event_id, least(5, a.zone_stage + case when a.zone_next_at is not null then 1 else 0 end)); select * into g from locations where id = b.goal; if g.id is null or v_danger or (b.goal_at is not null and b.goal_at < now() - interval '100 seconds') or not _in_circle(c, g.x, g.y) or (g.building is not null and (_sealed(a.id, g.building, g.level) or _sealed(a.id, g.building, 0))) then select l.id into v_goal from locations l where l.enabled and l.kind not in ('start', 'stairs') and l.id is distinct from t.location_id and l.id is distinct from b.done_loc and _in_circle(c, l.x, l.y) and (l.building is null or (not _sealed(a.id, l.building, l.level) and not _sealed(a.id, l.building, 0) and (v_brave or not exists (select 1 from lockdowns k where k.arena_id = a.id and not k.sealed and k.building = l.building and (k.level is null or k.level = l.level))))) and not (v_danger and l.building is not distinct from lk.building) order by (case when exists (select 1 from airdrops ad where ad.arena_id = a.id and ad.status = 'open' and ad.location_id = l.id) then 0.3 else 1 end) * (case when l.level > 0 then 1.5 else 1 end) * (0.012 + (l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2) * (0.2 + random()) limit 1; if v_goal is null then select l.id into v_goal from locations l where l.enabled and l.kind not in ('start', 'stairs') and l.level = 0 order by (l.x - coalesce(c[1], 0.5)) ^ 2 + (l.y - coalesce(c[2], 0.5)) ^ 2 limit 1; end if; update bots set goal = v_goal, goal_at = now() where team_id = t.id; select * into g from locations where id = v_goal; if g.id is null then return; end if; end if; if t.level = 0 and t.vehicle <> 'in' and t.buggy_x is not null and (sqrt((g.x - cur[1]) ^ 2 + (g.y - cur[2]) ^ 2) > 0.08 or (g.building is null and sqrt((g.x - cur[1]) ^ 2 + (g.y - cur[2]) ^ 2) > 0.03)) and sqrt((t.buggy_x - cur[1]) ^ 2 + (t.buggy_y - cur[2]) ^ 2) < 0.007 then begin perform captain_vehicle(tok, true); exception when others then null; end; return; end if; if t.level = 0 and t.vehicle <> 'in' and t.buggy_x is not null and (sqrt((g.x - cur[1]) ^ 2 + (g.y - cur[2]) ^ 2) > 0.08 or (g.building is null and sqrt((g.x - cur[1]) ^ 2 + (g.y - cur[2]) ^ 2) > 0.03)) then tx := t.buggy_x; ty := t.buggy_y; elsif t.level > 0 and (g.level = 0 or g.building is distinct from t.bldg or g.level <> t.level) then select * into bd from buildings where id = t.bldg; v_dir := case when g.building is not distinct from t.bldg and g.level > t.level then 1 else -1 end; tx := bd.stair_x; ty := bd.stair_y; elsif t.level = 0 and g.level > 0 then select * into bd from buildings where id = g.building; v_dir := 1; tx := bd.stair_x; ty := bd.stair_y; else tx := g.x + ((t.number * 37) % 9 - 4) * 0.0011; ty := g.y + ((t.number * 53) % 9 - 4) * 0.0011; v_final := true; end if; if tx is null then update bots set goal = null where team_id = t.id; return; end if; d := sqrt((tx - cur[1]) ^ 2 + (ty - cur[2]) ^ 2); if v_dir <> 0 and d < 0.012 then begin perform captain_stairs(tok, v_dir); exception when others then update bots set goal = null where team_id = t.id; end; return; end if; spd := _team_speed(t); dt := least(3.0, greatest(0.3, extract(epoch from now() - coalesce(t.pos_at, now() - interval '1 second')))); stepd := spd * dt; if d <= stepd then v_res := captain_steer(tok, tx, ty, 0, 0); if v_final then update bots set goal = null, wait_until = now() + _secs((1 + random() * 2)::numeric) where team_id = t.id; end if; return; end if; nx := cur[1] + (tx - cur[1]) * stepd / d; ny := cur[2] + (ty - cur[2]) * stepd / d; v_res := captain_steer(tok, nx, ny, (tx - cur[1]) / d * spd, (ty - cur[2]) / d * spd); if v_res ->> 'wall' is not null then v_side := case when t.number % 2 = 0 then 1 else -1 end; v_px := -(ty - cur[2]) / d * v_side; v_py := (tx - cur[1]) / d * v_side; v_res := captain_steer(tok, cur[1] + v_px * stepd, cur[2] + v_py * stepd, v_px * spd, v_py * spd); if v_res ->> 'wall' is not null then v_res := captain_steer(tok, cur[1] - v_px * stepd, cur[2] - v_py * stepd, -v_px * spd, -v_py * spd); end if; end if; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$;
